#include <iostream>
#include <memory>
#include <string>
#include <vector>

struct Employee {
    explicit Employee(const std::string& n) : name(n) {}
    ~Employee() {
        std::cout << name << " deleted\n";
    }
    std::string name;
    std::vector<std::shared_ptr<Employee>> reports;  // owns the people who report here
    std::weak_ptr<Employee> boss;                    // only watches the boss
};

void printBoss(const Employee& e) {
    if (auto b = e.boss.lock()) {
        std::cout << e.name << " reports to " << b->name << '\n';
    } else {
        std::cout << e.name << " has no boss\n";
    }
}

int main() {
    std::cout << std::boolalpha;
    std::weak_ptr<Employee> watch;
    {
        auto lee = std::make_shared<Employee>("lee");
        auto ana = std::make_shared<Employee>("ana");
        lee->reports.push_back(ana);
        ana->boss = lee;
        std::cout << "lee owners " << lee.use_count() << '\n';
        std::cout << "ana owners " << ana.use_count() << '\n';
        printBoss(*ana);
        printBoss(*lee);
        watch = lee;
        std::cout << "leaving block\n";
    }
    std::cout << "watch expired " << watch.expired() << '\n';
    return 0;
}
